sc_cat_item_producer.script:
/* global producer, sn_hr_le, cat_item */
(function() {

    new sn_hr_le.hr_ActivityUtils().createCaseFromProducer(current, producer, cat_item.sys_id);
    //   producer.portal_redirect = "?id=hoc_ohsm_confirmation&requestNumber=" + current.number;

    var chemical = JSON.parse(producer.hira_chemical_risks);
    var biological = JSON.parse(producer.hira_biological_risks);
    var energy = JSON.parse(producer.hira_energy_risks);
    var explosion = JSON.parse(producer.hira_explosion_risks);
    var physical = JSON.parse(producer.hira_physical_risks);
    var psychosocial = JSON.parse(producer.hira_psychosocial_risks);

    var gdt = new GlideDateTime();

    gdt.addYearsLocalTime(3);
    current.review_due = gdt.getDate();
    current.state = 1;
    current.assigned_to = producer.manager_name;

    //create a child case per MRVS line
    var work_task_desc = [];
    var frequency = [];
    var hazard_category = [];
    var hazard_subcat = [];
    var hazard_desc = [];
    var consequence = [];
    var reg_reference = [];
    var severity = [];
    var likelihood = [];
    var controls = [];
    var recommended = [];
    var actions = [];
    var start_date = [];
    var training = [];
    var comment = [];

    //populate array with MRVS - CHEMICAL
    var risks_identified_count = chemical.length;
    var i = 0;

    for (i = 0; i < risks_identified_count; i++) {
        work_task_desc.push(chemical[i].work_task_and_description_chemical);
        frequency.push(chemical[i].frequency_chemical);
        hazard_category.push("chemical");
        hazard_subcat.push(chemical[i].hazard_subcategory_chemical);
        hazard_desc.push(chemical[i].hazard_description_chemical);
        consequence.push(chemical[i].consequence_chemical);
        likelihood.push(chemical[i].likelihood_chemical);
        reg_reference.push(chemical[i].regulatory_reference_chemical);
        severity.push(chemical[i].severity_chemical);
        controls.push(chemical[i].controls_present_chemical);
        recommended.push(chemical[i].recommended_action_chemical);
        actions.push(chemical[i].action_s_taken_by_manager_chemical);
        start_date.push(chemical[i].start_date_for_implementing_control_measures_chemical);
        training.push(chemical[i].is_there_a_training_component_involved_chemical);
        comment.push(chemical[i].comments_chemical);
    }

    //populate array with MRVS - BIOLOGICAL
    risks_identified_count = biological.length;
    for (i = 0; i < risks_identified_count; i++) {
        work_task_desc.push(biological[i].work_task_and_description_bio);
        frequency.push(biological[i].frequency_bio);
        hazard_category.push('biological');
        hazard_subcat.push(biological[i].hazard_subcategory_bio);
        hazard_desc.push(biological[i].hazard_description_bio);
        consequence.push(biological[i].consequence_bio);
        likelihood.push(biological[i].likelihood_bio);
        reg_reference.push(biological[i].regulatory_reference_bio);
        severity.push(biological[i].severity_bio);
        controls.push(biological[i].controls_present_bio);
        recommended.push(biological[i].recommended_action_bio);
        actions.push(biological[i].action_s_taken_by_manager_bio);
        start_date.push(biological[i].start_date_for_implementing_control_measures_bio);
        training.push(biological[i].is_there_a_training_component_involved_bio);
        comment.push(biological[i].comments_bio);
    }

    //populate array with MRVS - ENERGY
    risks_identified_count = energy.length;
    for (i = 0; i < risks_identified_count; i++) {
        work_task_desc.push(energy[i].work_task_and_description_energy);
        frequency.push(energy[i].frequency_energy);
        hazard_category.push('energy');
        hazard_subcat.push(energy[i].hazard_subcategory_energy);
        hazard_desc.push(energy[i].hazard_description_energy);
        consequence.push(energy[i].consequence_energy);
        likelihood.push(energy[i].likelihood_energy);
        reg_reference.push(energy[i].regulatory_reference_energy);
        severity.push(energy[i].severity_energy);
        controls.push(energy[i].controls_present_energy);
        recommended.push(energy[i].recommended_action_energy);
        actions.push(energy[i].action_s_taken_by_manager_energy);
        start_date.push(energy[i].start_date_for_implementing_control_measures_energy);
        training.push(energy[i].is_there_a_training_component_involved_energy);
        comment.push(energy[i].comments_energy);
    }

    //populate array with MRVS - EXPLOSION
    risks_identified_count = explosion.length;
    for (i = 0; i < risks_identified_count; i++) {
        work_task_desc.push(explosion[i].work_task_and_description_explosion);
        frequency.push(explosion[i].frequency_explosion);
        hazard_category.push('explosion');
        hazard_subcat.push(explosion[i].hazard_subcategory_explosion);
        hazard_desc.push(explosion[i].hazard_description_explosion);
        consequence.push(explosion[i].consequence_explosion);
        likelihood.push(explosion[i].likelihood_explosion);
        reg_reference.push(explosion[i].regulatory_reference_explosion);
        severity.push(explosion[i].severity_explosion);
        controls.push(explosion[i].controls_present_explosion);
        recommended.push(explosion[i].recommended_action_explosion);
        actions.push(explosion[i].action_s_taken_by_manager_explosion);
        start_date.push(explosion[i].start_date_for_implementing_control_measures_explosion);
        training.push(explosion[i].is_there_a_training_component_involved_explosion);
        comment.push(explosion[i].comments_explosion);
    }

    //populate array with MRVS - PHYSICAL
    risks_identified_count = physical.length;
    for (i = 0; i < risks_identified_count; i++) {
        work_task_desc.push(physical[i].work_task_and_description_physical);
        frequency.push(physical[i].frequency_physical);
        hazard_category.push('physical');
        hazard_subcat.push(physical[i].hazard_subcategory_physical);
        hazard_desc.push(physical[i].hazard_description_physical);
        consequence.push(physical[i].consequence_physical);
        likelihood.push(physical[i].likelihood_physical);
        reg_reference.push(physical[i].regulatory_reference_physical);
        severity.push(physical[i].severity_physical);
        controls.push(physical[i].controls_present_physical);
        recommended.push(physical[i].recommended_action_physical);
        actions.push(physical[i].action_s_taken_by_manager_physical);
        start_date.push(physical[i].start_date_for_implementing_control_measures_physical);
        training.push(physical[i].is_there_a_training_component_involved_physical);
        comment.push(physical[i].comments_physical);
    }

    //populate array with MRVS - PSYCHOSOCIAL
    risks_identified_count = psychosocial.length;
    for (i = 0; i < risks_identified_count; i++) {
        work_task_desc.push(psychosocial[i].work_task_and_description_ps);
        frequency.push(psychosocial[i].frequency_ps);
        hazard_category.push('psychosocial');
        hazard_subcat.push(psychosocial[i].hazard_subcategory_ps);
        hazard_desc.push(psychosocial[i].hazard_description_ps);
        consequence.push(psychosocial[i].consequence_ps);
        likelihood.push(psychosocial[i].likelihood_ps);
        reg_reference.push(psychosocial[i].regulatory_reference_ps);
        severity.push(psychosocial[i].severity_ps);
        controls.push(psychosocial[i].controls_present_ps);
        recommended.push(psychosocial[i].recommended_action_ps);
        actions.push(psychosocial[i].action_s_taken_by_manager_ps);
        start_date.push(psychosocial[i].start_date_for_implementing_control_measures_ps);
        training.push(psychosocial[i].is_there_a_training_component_involved_ps);
        comment.push(psychosocial[i].comments_ps);
    }

    if (work_task_desc.length > 0) {
        for (var x = 0; x < work_task_desc.length; x++) {
            var grItem = new GlideRecord('x_hccc_hoc_ohs_hazard_investigation_and_risk_assessment');

            grItem.initialize();
            //grItem.hr_service = '2519e8648754515050d2eca73cbb35d4'; //HIRA Line Item		
            grItem.work_task_description = work_task_desc[x];
            grItem.hira_case = current.sys_id;
            grItem.frequency = frequency[x];
            grItem.hazard_category = hazard_category[x];
            grItem.hazard_subcategory = hazard_subcat[x];
            grItem.hazard_description = hazard_desc[x];
            grItem.consequence = consequence[x];
            grItem.regulatory_reference = reg_reference[x];
            grItem.likelihood = likelihood[x];
            grItem.severity = severity[x];
            grItem.controls_present = controls[x];
            grItem.recommended_action = recommended[x];
            grItem.actions_taken = actions[x];
            grItem.start_date = start_date[x];
            grItem.training = training[x];
            grItem.comment = comment[x];
            grItem.insert();

        }
    }
})();
